INSERT IGNORE INTO `contract` VALUES (11, 2, '示例劳动合同', '劳动合同', 'XX科技有限公司', '张三', NULL, '劳动合同\n甲方：XX科技有限公司  乙方：张三\n一、合同期限：自2024年7月1日起至2025年6月30日止，其中试用期为6个月。\n二、工资：月薪6000元，每月15日发放；试用期工资按80%发放。\n三、社保：甲方自乙方转正后为其缴纳社会保险。\n四、加班：因工作需要加班的，公司安排调休，不另行支付加班费。\n五、竞业限制：乙方离职后两年内不得从事同类业务，公司不支付经济补偿。\n六、解除：乙方提前离职需向甲方支付违约金20000元。', '高', 2, 1, '2026-09-16 08:25:14', '2026-09-16 08:25:14');
INSERT IGNORE INTO `contract` VALUES (12, 2, '01_数学建模国赛【赛题分析】万能提示词', '劳动合同', '', '', NULL, '数学建模国赛{赛题分析}万能提示词\n\n（检测/修改/撰写三模式完整版）\n\n第1步：对赛题进行深度分析，输出分析报告+8列速查表+国奖级模型推荐+标准化交接包。支持检测评估模式。\n\n【通用规范引用·V6.0】排版格式、公式零乱码、流程图与示意图、HTML要点解析、三模式运行机制、检测评估+自动整改、HTML整改报告格式等通用规范，详见《超级提示词V6.0》。V6.0核心：①三模式运行(串联+独立+检测整改) ②检测+自动整改一体化 ③标准化交接包 ④自动检测适配 ⑤章节对标优秀论文 ⑥C题数据侧写 ⑦示意图+算法步骤表+完整模型给出 ⑧检测整改强制输出HTML报告+整改后成果。\n\n────────────────────────────────────────────────\n\n【三模式运行机制】V6.0核心\n\n本提示词支持三种运行模式，自动检测适配，确保串联性、独立性、检测评估能力三保障：\n\n模式一：串联模式（按顺序运行时自动启用）\n\n• 运行开始时自动检测是否存在「无（全流程第一步）标准化交接包」\n\n• 检测到交接包 → 自动读取其中的国奖级推荐模型、创新点、预处理方案等核心数据，基于其继续执行\n\n• 严格遵循前一步给出的国奖级建模方案，不得随意降级或更换模型\n\n• 本步完成后输出「赛题分析标准化交接包」，供下一步读取\n\n模式二：独立模式（单独使用本提示词时自动启用）\n\n• 未检测到前一步交接包 → 自动进入独立模式，无需依托任何前序提示词\n\n• 独立模式下自行完成前置工作：本步是全流程第一步，独立模式即为默认模式，直接基于题目和附件数据进行分析\n\n• 独立模式下输出质量与串联模式完全一致，同样达到国奖级标准\n\n• 本步完成后同样输出「赛题分析标准化交接包」，可与其他步骤衔接\n\n模式三：检测评估+自动整改模式（V6.0核心升级·学员上传成果时自动启用）\n\n【V6.0核心升级】当检测到学员上传的是已有论文/解题思路/代码/图表等成果（而非原始题目+数据）时，自动进入检测评估+自动整改模式！不仅检测问题，还基于提示词要求自动修改优化，消除检测出的问题！\n\n• 功能1【检测】：将学员上传的成果与国奖级标准进行多维度对比检测，评估是否达到国赛国奖级要求\n\n• 功能2【自动整改】：基于检测出的问题，按照本提示词的国奖级要求自动修改和优化学员上传的成果，消除问题\n\n• 评估维度：题型判断准确性/隐含条件挖掘深度/模型推荐合理性/创新点质量/评分点覆盖度/题意理解准确性\n\n• 整改流程：①多维度检测→②生成HTML检测报告→③按优先级(P0→P1→P2)自动整改→④整改后复检→⑤输出整改后成果+HTML整改报告(含整改前后对比)\n\n• 整改原则：能自动修改的自动修改（如格式/排版/公式/图表/代码），不能自动修改的给出详细修改方案（如模型重构/创新点设计），不得只检测不整改！\n\n• 输出：强制输出①整改后的成果文件（修改后的论文/代码/图表）②HTML格式的整改报告（文件名：整改报告_学员成果名称.html），报告最开始给出检测结果总览，然后列出整改清单+整改前后对比+复检结果\n\n• HTML整改报告必须包含8个部分：①检测结果总览(等级+总分+核心问题) ②多维度评分可视化 ③分维度详细分析 ④国奖级标准对照表 ⑤优先级整改清单(P0/P1/P2) ⑥整改前后对比(逐项展示修改内容) ⑦复检结果(整改后重新检测得分) ⑧底部信息栏\n\n• 评估等级：国奖级(≥90分) / 国一(80-89) / 国二(70-79) / 省一(60-69) / 省二(50-59) / 需大幅改进(<50)\n\n• 如学员明确只需要检测不需要整改，则只输出HTML检测报告；默认执行检测+自动整改一体化\n\n「赛题分析标准化交接包」输出格式（强制）\n\n本步完成后必须输出以下结构化交接包（JSON格式），供下一步自动读取：\n\n{ "题型": "A/B/C/D/E/混合" "各小问国奖版推荐模型": "问题一:XXX模型; 问题二:XXX模型..." "核心创新点清单": "创新点1:XXX(怎么做+效果+验证); 创新点2:XXX..." "关键隐含条件清单": "隐含条件1:XXX(数学表达); 隐含条件2:XXX..." "数据预处理重点": "缺失值处理/异常值处理/特征工程/防泄露要点" "检验方向建议": "问题一:灵敏度分析; 问题二:误差分析..." "评分点与易错点": "评分点:XXX; 易错点:XXX..."}\n\n【三模式铁律】无论哪种模式，输出质量标准完全一致！串联模式必须严格遵循前一步方案，独立模式必须自行完成前置工作，检测评估+自动整改模式必须既检测又整改，不得只检测不整改！不得因模式不同而降低质量！\n\n──────────────────────────────────────────────────\n\n一、输入（三模式）\n\n• 串联模式：无（本步是第一步）\n\n• 独立模式：赛题题目+附件数据（默认模式）\n\n• 检测评估模式：学员上传的赛题分析报告/解题思路文档\n\n二、输出\n\n• 解题模式：①赛题分析报告 ②8列速查表 ③国奖版推荐模型 ④核心创新点清单 ⑤隐含条件清单 ⑥数据预处理重点 ⑦标准化交接包\n\n• 检测评估模式：HTML评估报告（强制）\n\n三、国奖优秀论文赛题分析共性特点（补充原始细节）\n\n• 隐含条件挖掘深度：国奖论文隐含条件数量≥显性条件50%，每条有数学表达和建模影响\n\n• 模型推荐精准：直接给出国奖级创新模型，而非泛泛的「可以用优化模型」\n\n• 创新点具体：每个创新点说明「创新什么+为什么+怎么做+预期效果+如何验证」五要素\n\n• 评分导向：明确指出每个小问的评分点(3-5个)和易错点(2-3个)\n\n• 题型判断准确：A题机理优化/B题机理优化/C题数据分析/D题运筹优化/E题机理预测\n\n四、题意理解的常见误区（必须避免·补充原始细节）\n\n• 误区1：只看显性条件，忽略隐含条件（最致命）\n\n• 误区2：把问题想简单，用过于基础的模型（如只用线性规划解决复杂优化）\n\n• 误区3：模型推荐泛泛而谈，不具体到算法和创新点\n\n• 误区4：忽略题目中的约束条件（如额定功率、时间限制、资源约束）\n\n• 误区5：不区分省奖版和国奖版，直接给最简单的模型\n\n五、8大分析维度\n\n维度\n\n核心内容\n\n1 题目背景\n\n领域+核心问题+现实价值+评委考察意图\n\n2 已知条件\n\n逐句列出显性条件+数据+参数+约束+附件信息\n\n3 隐含条件(最高优先级)\n\n6维度挖掘：物理定律/数学约束/数据特征/边界条件/常识假设/评分导向\n\n4 核心要求\n\n每小问核心目标+评分点(3-5个)+易错点(2-3个)\n\n5 数学本质\n\n问题类型(优化/预测/分类/评价/机理)+数学工具+变量目标约束\n\n6 数据特征\n\n数据质量+分布+相关性+时空特征(C题重点)\n\n7 难点挑战\n\n建模/求解/数据/创新难点+解决策略\n\n8 创新空间\n\n算法改进/跨领域迁移/多模型融合+省奖国奖策略\n\n六、隐含条件挖掘（获奖关键）\n\n隐含条件数量必须≥显性条件的50%！每条按五要素：描述+来源+数学表达+建模影响+遗漏后果\n\n• 6维度：①物理/实际定律 ②数学约束 ③数据特征 ④边界条件 ⑤常识假设 ⑥评分导向\n\n七、省奖/国奖双轨思路\n\n版本\n\n要求\n\n省奖版\n\n经典成熟模型，实现简单稳妥，有基本问题特化处理\n\n国奖版(最终建模以此为准)\n\n经典模型基础上有针对性改进，至少1个真创新点(五要素：什么+为什么+怎么做+效果+验证)\n\n八、8列速查表（强制输出）\n\n列\n\n内容\n\n1\n\n小问编号\n\n2\n\n核心要求\n\n3\n\n数学本质\n\n4\n\n省奖版模型\n\n5\n\n国奖版模型\n\n6\n\n核心创新点\n\n7\n\n关键评分点\n\n8\n\n高频易错点\n\n九、检测评估模式评估维度\n\n维度\n\n国奖级标准\n\n评估要点\n\n题型判断\n\n准确判断题型(A/B/C/D/E)\n\n是否正确判断题型，是否说明判断依据\n\n隐含条件挖掘\n\n≥显性条件50%，每条有数学表达\n\n隐含条件数量、深度、数学表达、建模影响\n\n模型推荐\n\n直接给出国奖级创新模型\n\n模型是否具体到算法，是否有创新点，是否适配题目\n\n创新点质量\n\n每个创新点五要素完整\n\n创新点是否真创新(非简单应用)，五要素是否完整\n\n评分点覆盖\n\n每问3-5个评分点\n\n是否覆盖主要评分点，是否指出易错点\n\n题意理解\n\n无明显误解\n\n是否误解题目要求，是否忽略约束条件\n\n十、本提示词整改能力（检测+自动整改）\n\n整改类型\n\n可自动整改的内容\n\n整改方式\n\nP0致命\n\n题型判断错误、隐含条件严重不足、模型推荐过于简单\n\n重新判断题型+补充隐含条件+升级为国奖级创新模型\n\nP1重要\n\n创新点不具体、评分点覆盖不全、题意理解有偏差\n\n补充创新点五要素+补充评分点+修正题意理解\n\nP2优化\n\n格式排版、表述不够学术、结构不够清晰\n\n优化格式+学术化表述+调整结构\n\n需手动\n\n模型完全错误需要重构、核心思路完全偏离\n\n给出详细的重构方案和建议，需学员确认后执行\n\n整改后输出：修改后的赛题分析报告_已整改.docx + HTML整改报告（含整改前后对比+复检结果）\n\n──────────────────────────────────────────────────\n\n【赛题分析V6.0结束】解题模式输出标准化交接包，检测评估模式输出HTML报告。', '低', 0, 1, '2026-09-16 08:33:26', '2026-09-16 08:33:26');
INSERT IGNORE INTO `contract` VALUES (13, 2, '01_数学建模国赛【赛题分析】万能提示词', '劳动合同', '', '', NULL, '数学建模国赛{赛题分析}万能提示词\n\n（检测/修改/撰写三模式完整版）\n\n第1步：对赛题进行深度分析，输出分析报告+8列速查表+国奖级模型推荐+标准化交接包。支持检测评估模式。\n\n【通用规范引用·V6.0】排版格式、公式零乱码、流程图与示意图、HTML要点解析、三模式运行机制、检测评估+自动整改、HTML整改报告格式等通用规范，详见《超级提示词V6.0》。V6.0核心：①三模式运行(串联+独立+检测整改) ②检测+自动整改一体化 ③标准化交接包 ④自动检测适配 ⑤章节对标优秀论文 ⑥C题数据侧写 ⑦示意图+算法步骤表+完整模型给出 ⑧检测整改强制输出HTML报告+整改后成果。\n\n────────────────────────────────────────────────\n\n【三模式运行机制】V6.0核心\n\n本提示词支持三种运行模式，自动检测适配，确保串联性、独立性、检测评估能力三保障：\n\n模式一：串联模式（按顺序运行时自动启用）\n\n• 运行开始时自动检测是否存在「无（全流程第一步）标准化交接包」\n\n• 检测到交接包 → 自动读取其中的国奖级推荐模型、创新点、预处理方案等核心数据，基于其继续执行\n\n• 严格遵循前一步给出的国奖级建模方案，不得随意降级或更换模型\n\n• 本步完成后输出「赛题分析标准化交接包」，供下一步读取\n\n模式二：独立模式（单独使用本提示词时自动启用）\n\n• 未检测到前一步交接包 → 自动进入独立模式，无需依托任何前序提示词\n\n• 独立模式下自行完成前置工作：本步是全流程第一步，独立模式即为默认模式，直接基于题目和附件数据进行分析\n\n• 独立模式下输出质量与串联模式完全一致，同样达到国奖级标准\n\n• 本步完成后同样输出「赛题分析标准化交接包」，可与其他步骤衔接\n\n模式三：检测评估+自动整改模式（V6.0核心升级·学员上传成果时自动启用）\n\n【V6.0核心升级】当检测到学员上传的是已有论文/解题思路/代码/图表等成果（而非原始题目+数据）时，自动进入检测评估+自动整改模式！不仅检测问题，还基于提示词要求自动修改优化，消除检测出的问题！\n\n• 功能1【检测】：将学员上传的成果与国奖级标准进行多维度对比检测，评估是否达到国赛国奖级要求\n\n• 功能2【自动整改】：基于检测出的问题，按照本提示词的国奖级要求自动修改和优化学员上传的成果，消除问题\n\n• 评估维度：题型判断准确性/隐含条件挖掘深度/模型推荐合理性/创新点质量/评分点覆盖度/题意理解准确性\n\n• 整改流程：①多维度检测→②生成HTML检测报告→③按优先级(P0→P1→P2)自动整改→④整改后复检→⑤输出整改后成果+HTML整改报告(含整改前后对比)\n\n• 整改原则：能自动修改的自动修改（如格式/排版/公式/图表/代码），不能自动修改的给出详细修改方案（如模型重构/创新点设计），不得只检测不整改！\n\n• 输出：强制输出①整改后的成果文件（修改后的论文/代码/图表）②HTML格式的整改报告（文件名：整改报告_学员成果名称.html），报告最开始给出检测结果总览，然后列出整改清单+整改前后对比+复检结果\n\n• HTML整改报告必须包含8个部分：①检测结果总览(等级+总分+核心问题) ②多维度评分可视化 ③分维度详细分析 ④国奖级标准对照表 ⑤优先级整改清单(P0/P1/P2) ⑥整改前后对比(逐项展示修改内容) ⑦复检结果(整改后重新检测得分) ⑧底部信息栏\n\n• 评估等级：国奖级(≥90分) / 国一(80-89) / 国二(70-79) / 省一(60-69) / 省二(50-59) / 需大幅改进(<50)\n\n• 如学员明确只需要检测不需要整改，则只输出HTML检测报告；默认执行检测+自动整改一体化\n\n「赛题分析标准化交接包」输出格式（强制）\n\n本步完成后必须输出以下结构化交接包（JSON格式），供下一步自动读取：\n\n{ "题型": "A/B/C/D/E/混合" "各小问国奖版推荐模型": "问题一:XXX模型; 问题二:XXX模型..." "核心创新点清单": "创新点1:XXX(怎么做+效果+验证); 创新点2:XXX..." "关键隐含条件清单": "隐含条件1:XXX(数学表达); 隐含条件2:XXX..." "数据预处理重点": "缺失值处理/异常值处理/特征工程/防泄露要点" "检验方向建议": "问题一:灵敏度分析; 问题二:误差分析..." "评分点与易错点": "评分点:XXX; 易错点:XXX..."}\n\n【三模式铁律】无论哪种模式，输出质量标准完全一致！串联模式必须严格遵循前一步方案，独立模式必须自行完成前置工作，检测评估+自动整改模式必须既检测又整改，不得只检测不整改！不得因模式不同而降低质量！\n\n──────────────────────────────────────────────────\n\n一、输入（三模式）\n\n• 串联模式：无（本步是第一步）\n\n• 独立模式：赛题题目+附件数据（默认模式）\n\n• 检测评估模式：学员上传的赛题分析报告/解题思路文档\n\n二、输出\n\n• 解题模式：①赛题分析报告 ②8列速查表 ③国奖版推荐模型 ④核心创新点清单 ⑤隐含条件清单 ⑥数据预处理重点 ⑦标准化交接包\n\n• 检测评估模式：HTML评估报告（强制）\n\n三、国奖优秀论文赛题分析共性特点（补充原始细节）\n\n• 隐含条件挖掘深度：国奖论文隐含条件数量≥显性条件50%，每条有数学表达和建模影响\n\n• 模型推荐精准：直接给出国奖级创新模型，而非泛泛的「可以用优化模型」\n\n• 创新点具体：每个创新点说明「创新什么+为什么+怎么做+预期效果+如何验证」五要素\n\n• 评分导向：明确指出每个小问的评分点(3-5个)和易错点(2-3个)\n\n• 题型判断准确：A题机理优化/B题机理优化/C题数据分析/D题运筹优化/E题机理预测\n\n四、题意理解的常见误区（必须避免·补充原始细节）\n\n• 误区1：只看显性条件，忽略隐含条件（最致命）\n\n• 误区2：把问题想简单，用过于基础的模型（如只用线性规划解决复杂优化）\n\n• 误区3：模型推荐泛泛而谈，不具体到算法和创新点\n\n• 误区4：忽略题目中的约束条件（如额定功率、时间限制、资源约束）\n\n• 误区5：不区分省奖版和国奖版，直接给最简单的模型\n\n五、8大分析维度\n\n维度\n\n核心内容\n\n1 题目背景\n\n领域+核心问题+现实价值+评委考察意图\n\n2 已知条件\n\n逐句列出显性条件+数据+参数+约束+附件信息\n\n3 隐含条件(最高优先级)\n\n6维度挖掘：物理定律/数学约束/数据特征/边界条件/常识假设/评分导向\n\n4 核心要求\n\n每小问核心目标+评分点(3-5个)+易错点(2-3个)\n\n5 数学本质\n\n问题类型(优化/预测/分类/评价/机理)+数学工具+变量目标约束\n\n6 数据特征\n\n数据质量+分布+相关性+时空特征(C题重点)\n\n7 难点挑战\n\n建模/求解/数据/创新难点+解决策略\n\n8 创新空间\n\n算法改进/跨领域迁移/多模型融合+省奖国奖策略\n\n六、隐含条件挖掘（获奖关键）\n\n隐含条件数量必须≥显性条件的50%！每条按五要素：描述+来源+数学表达+建模影响+遗漏后果\n\n• 6维度：①物理/实际定律 ②数学约束 ③数据特征 ④边界条件 ⑤常识假设 ⑥评分导向\n\n七、省奖/国奖双轨思路\n\n版本\n\n要求\n\n省奖版\n\n经典成熟模型，实现简单稳妥，有基本问题特化处理\n\n国奖版(最终建模以此为准)\n\n经典模型基础上有针对性改进，至少1个真创新点(五要素：什么+为什么+怎么做+效果+验证)\n\n八、8列速查表（强制输出）\n\n列\n\n内容\n\n1\n\n小问编号\n\n2\n\n核心要求\n\n3\n\n数学本质\n\n4\n\n省奖版模型\n\n5\n\n国奖版模型\n\n6\n\n核心创新点\n\n7\n\n关键评分点\n\n8\n\n高频易错点\n\n九、检测评估模式评估维度\n\n维度\n\n国奖级标准\n\n评估要点\n\n题型判断\n\n准确判断题型(A/B/C/D/E)\n\n是否正确判断题型，是否说明判断依据\n\n隐含条件挖掘\n\n≥显性条件50%，每条有数学表达\n\n隐含条件数量、深度、数学表达、建模影响\n\n模型推荐\n\n直接给出国奖级创新模型\n\n模型是否具体到算法，是否有创新点，是否适配题目\n\n创新点质量\n\n每个创新点五要素完整\n\n创新点是否真创新(非简单应用)，五要素是否完整\n\n评分点覆盖\n\n每问3-5个评分点\n\n是否覆盖主要评分点，是否指出易错点\n\n题意理解\n\n无明显误解\n\n是否误解题目要求，是否忽略约束条件\n\n十、本提示词整改能力（检测+自动整改）\n\n整改类型\n\n可自动整改的内容\n\n整改方式\n\nP0致命\n\n题型判断错误、隐含条件严重不足、模型推荐过于简单\n\n重新判断题型+补充隐含条件+升级为国奖级创新模型\n\nP1重要\n\n创新点不具体、评分点覆盖不全、题意理解有偏差\n\n补充创新点五要素+补充评分点+修正题意理解\n\nP2优化\n\n格式排版、表述不够学术、结构不够清晰\n\n优化格式+学术化表述+调整结构\n\n需手动\n\n模型完全错误需要重构、核心思路完全偏离\n\n给出详细的重构方案和建议，需学员确认后执行\n\n整改后输出：修改后的赛题分析报告_已整改.docx + HTML整改报告（含整改前后对比+复检结果）\n\n──────────────────────────────────────────────────\n\n【赛题分析V6.0结束】解题模式输出标准化交接包，检测评估模式输出HTML报告。', '低', 0, 1, '2026-09-16 08:33:29', '2026-09-16 08:33:29');
INSERT IGNORE INTO `contract` VALUES (14, 2, '01_数学建模国赛【赛题分析】万能提示词', '劳动合同', '', '', NULL, '数学建模国赛{赛题分析}万能提示词\n\n（检测/修改/撰写三模式完整版）\n\n第1步：对赛题进行深度分析，输出分析报告+8列速查表+国奖级模型推荐+标准化交接包。支持检测评估模式。\n\n【通用规范引用·V6.0】排版格式、公式零乱码、流程图与示意图、HTML要点解析、三模式运行机制、检测评估+自动整改、HTML整改报告格式等通用规范，详见《超级提示词V6.0》。V6.0核心：①三模式运行(串联+独立+检测整改) ②检测+自动整改一体化 ③标准化交接包 ④自动检测适配 ⑤章节对标优秀论文 ⑥C题数据侧写 ⑦示意图+算法步骤表+完整模型给出 ⑧检测整改强制输出HTML报告+整改后成果。\n\n────────────────────────────────────────────────\n\n【三模式运行机制】V6.0核心\n\n本提示词支持三种运行模式，自动检测适配，确保串联性、独立性、检测评估能力三保障：\n\n模式一：串联模式（按顺序运行时自动启用）\n\n• 运行开始时自动检测是否存在「无（全流程第一步）标准化交接包」\n\n• 检测到交接包 → 自动读取其中的国奖级推荐模型、创新点、预处理方案等核心数据，基于其继续执行\n\n• 严格遵循前一步给出的国奖级建模方案，不得随意降级或更换模型\n\n• 本步完成后输出「赛题分析标准化交接包」，供下一步读取\n\n模式二：独立模式（单独使用本提示词时自动启用）\n\n• 未检测到前一步交接包 → 自动进入独立模式，无需依托任何前序提示词\n\n• 独立模式下自行完成前置工作：本步是全流程第一步，独立模式即为默认模式，直接基于题目和附件数据进行分析\n\n• 独立模式下输出质量与串联模式完全一致，同样达到国奖级标准\n\n• 本步完成后同样输出「赛题分析标准化交接包」，可与其他步骤衔接\n\n模式三：检测评估+自动整改模式（V6.0核心升级·学员上传成果时自动启用）\n\n【V6.0核心升级】当检测到学员上传的是已有论文/解题思路/代码/图表等成果（而非原始题目+数据）时，自动进入检测评估+自动整改模式！不仅检测问题，还基于提示词要求自动修改优化，消除检测出的问题！\n\n• 功能1【检测】：将学员上传的成果与国奖级标准进行多维度对比检测，评估是否达到国赛国奖级要求\n\n• 功能2【自动整改】：基于检测出的问题，按照本提示词的国奖级要求自动修改和优化学员上传的成果，消除问题\n\n• 评估维度：题型判断准确性/隐含条件挖掘深度/模型推荐合理性/创新点质量/评分点覆盖度/题意理解准确性\n\n• 整改流程：①多维度检测→②生成HTML检测报告→③按优先级(P0→P1→P2)自动整改→④整改后复检→⑤输出整改后成果+HTML整改报告(含整改前后对比)\n\n• 整改原则：能自动修改的自动修改（如格式/排版/公式/图表/代码），不能自动修改的给出详细修改方案（如模型重构/创新点设计），不得只检测不整改！\n\n• 输出：强制输出①整改后的成果文件（修改后的论文/代码/图表）②HTML格式的整改报告（文件名：整改报告_学员成果名称.html），报告最开始给出检测结果总览，然后列出整改清单+整改前后对比+复检结果\n\n• HTML整改报告必须包含8个部分：①检测结果总览(等级+总分+核心问题) ②多维度评分可视化 ③分维度详细分析 ④国奖级标准对照表 ⑤优先级整改清单(P0/P1/P2) ⑥整改前后对比(逐项展示修改内容) ⑦复检结果(整改后重新检测得分) ⑧底部信息栏\n\n• 评估等级：国奖级(≥90分) / 国一(80-89) / 国二(70-79) / 省一(60-69) / 省二(50-59) / 需大幅改进(<50)\n\n• 如学员明确只需要检测不需要整改，则只输出HTML检测报告；默认执行检测+自动整改一体化\n\n「赛题分析标准化交接包」输出格式（强制）\n\n本步完成后必须输出以下结构化交接包（JSON格式），供下一步自动读取：\n\n{ "题型": "A/B/C/D/E/混合" "各小问国奖版推荐模型": "问题一:XXX模型; 问题二:XXX模型..." "核心创新点清单": "创新点1:XXX(怎么做+效果+验证); 创新点2:XXX..." "关键隐含条件清单": "隐含条件1:XXX(数学表达); 隐含条件2:XXX..." "数据预处理重点": "缺失值处理/异常值处理/特征工程/防泄露要点" "检验方向建议": "问题一:灵敏度分析; 问题二:误差分析..." "评分点与易错点": "评分点:XXX; 易错点:XXX..."}\n\n【三模式铁律】无论哪种模式，输出质量标准完全一致！串联模式必须严格遵循前一步方案，独立模式必须自行完成前置工作，检测评估+自动整改模式必须既检测又整改，不得只检测不整改！不得因模式不同而降低质量！\n\n──────────────────────────────────────────────────\n\n一、输入（三模式）\n\n• 串联模式：无（本步是第一步）\n\n• 独立模式：赛题题目+附件数据（默认模式）\n\n• 检测评估模式：学员上传的赛题分析报告/解题思路文档\n\n二、输出\n\n• 解题模式：①赛题分析报告 ②8列速查表 ③国奖版推荐模型 ④核心创新点清单 ⑤隐含条件清单 ⑥数据预处理重点 ⑦标准化交接包\n\n• 检测评估模式：HTML评估报告（强制）\n\n三、国奖优秀论文赛题分析共性特点（补充原始细节）\n\n• 隐含条件挖掘深度：国奖论文隐含条件数量≥显性条件50%，每条有数学表达和建模影响\n\n• 模型推荐精准：直接给出国奖级创新模型，而非泛泛的「可以用优化模型」\n\n• 创新点具体：每个创新点说明「创新什么+为什么+怎么做+预期效果+如何验证」五要素\n\n• 评分导向：明确指出每个小问的评分点(3-5个)和易错点(2-3个)\n\n• 题型判断准确：A题机理优化/B题机理优化/C题数据分析/D题运筹优化/E题机理预测\n\n四、题意理解的常见误区（必须避免·补充原始细节）\n\n• 误区1：只看显性条件，忽略隐含条件（最致命）\n\n• 误区2：把问题想简单，用过于基础的模型（如只用线性规划解决复杂优化）\n\n• 误区3：模型推荐泛泛而谈，不具体到算法和创新点\n\n• 误区4：忽略题目中的约束条件（如额定功率、时间限制、资源约束）\n\n• 误区5：不区分省奖版和国奖版，直接给最简单的模型\n\n五、8大分析维度\n\n维度\n\n核心内容\n\n1 题目背景\n\n领域+核心问题+现实价值+评委考察意图\n\n2 已知条件\n\n逐句列出显性条件+数据+参数+约束+附件信息\n\n3 隐含条件(最高优先级)\n\n6维度挖掘：物理定律/数学约束/数据特征/边界条件/常识假设/评分导向\n\n4 核心要求\n\n每小问核心目标+评分点(3-5个)+易错点(2-3个)\n\n5 数学本质\n\n问题类型(优化/预测/分类/评价/机理)+数学工具+变量目标约束\n\n6 数据特征\n\n数据质量+分布+相关性+时空特征(C题重点)\n\n7 难点挑战\n\n建模/求解/数据/创新难点+解决策略\n\n8 创新空间\n\n算法改进/跨领域迁移/多模型融合+省奖国奖策略\n\n六、隐含条件挖掘（获奖关键）\n\n隐含条件数量必须≥显性条件的50%！每条按五要素：描述+来源+数学表达+建模影响+遗漏后果\n\n• 6维度：①物理/实际定律 ②数学约束 ③数据特征 ④边界条件 ⑤常识假设 ⑥评分导向\n\n七、省奖/国奖双轨思路\n\n版本\n\n要求\n\n省奖版\n\n经典成熟模型，实现简单稳妥，有基本问题特化处理\n\n国奖版(最终建模以此为准)\n\n经典模型基础上有针对性改进，至少1个真创新点(五要素：什么+为什么+怎么做+效果+验证)\n\n八、8列速查表（强制输出）\n\n列\n\n内容\n\n1\n\n小问编号\n\n2\n\n核心要求\n\n3\n\n数学本质\n\n4\n\n省奖版模型\n\n5\n\n国奖版模型\n\n6\n\n核心创新点\n\n7\n\n关键评分点\n\n8\n\n高频易错点\n\n九、检测评估模式评估维度\n\n维度\n\n国奖级标准\n\n评估要点\n\n题型判断\n\n准确判断题型(A/B/C/D/E)\n\n是否正确判断题型，是否说明判断依据\n\n隐含条件挖掘\n\n≥显性条件50%，每条有数学表达\n\n隐含条件数量、深度、数学表达、建模影响\n\n模型推荐\n\n直接给出国奖级创新模型\n\n模型是否具体到算法，是否有创新点，是否适配题目\n\n创新点质量\n\n每个创新点五要素完整\n\n创新点是否真创新(非简单应用)，五要素是否完整\n\n评分点覆盖\n\n每问3-5个评分点\n\n是否覆盖主要评分点，是否指出易错点\n\n题意理解\n\n无明显误解\n\n是否误解题目要求，是否忽略约束条件\n\n十、本提示词整改能力（检测+自动整改）\n\n整改类型\n\n可自动整改的内容\n\n整改方式\n\nP0致命\n\n题型判断错误、隐含条件严重不足、模型推荐过于简单\n\n重新判断题型+补充隐含条件+升级为国奖级创新模型\n\nP1重要\n\n创新点不具体、评分点覆盖不全、题意理解有偏差\n\n补充创新点五要素+补充评分点+修正题意理解\n\nP2优化\n\n格式排版、表述不够学术、结构不够清晰\n\n优化格式+学术化表述+调整结构\n\n需手动\n\n模型完全错误需要重构、核心思路完全偏离\n\n给出详细的重构方案和建议，需学员确认后执行\n\n整改后输出：修改后的赛题分析报告_已整改.docx + HTML整改报告（含整改前后对比+复检结果）\n\n──────────────────────────────────────────────────\n\n【赛题分析V6.0结束】解题模式输出标准化交接包，检测评估模式输出HTML报告。', '低', 0, 1, '2026-09-16 08:33:30', '2026-09-16 08:33:30');
INSERT IGNORE INTO `contract` VALUES (15, 2, '01_数学建模国赛【赛题分析】万能提示词', '劳动合同', '', '', NULL, '数学建模国赛{赛题分析}万能提示词\n\n（检测/修改/撰写三模式完整版）\n\n第1步：对赛题进行深度分析，输出分析报告+8列速查表+国奖级模型推荐+标准化交接包。支持检测评估模式。\n\n【通用规范引用·V6.0】排版格式、公式零乱码、流程图与示意图、HTML要点解析、三模式运行机制、检测评估+自动整改、HTML整改报告格式等通用规范，详见《超级提示词V6.0》。V6.0核心：①三模式运行(串联+独立+检测整改) ②检测+自动整改一体化 ③标准化交接包 ④自动检测适配 ⑤章节对标优秀论文 ⑥C题数据侧写 ⑦示意图+算法步骤表+完整模型给出 ⑧检测整改强制输出HTML报告+整改后成果。\n\n────────────────────────────────────────────────\n\n【三模式运行机制】V6.0核心\n\n本提示词支持三种运行模式，自动检测适配，确保串联性、独立性、检测评估能力三保障：\n\n模式一：串联模式（按顺序运行时自动启用）\n\n• 运行开始时自动检测是否存在「无（全流程第一步）标准化交接包」\n\n• 检测到交接包 → 自动读取其中的国奖级推荐模型、创新点、预处理方案等核心数据，基于其继续执行\n\n• 严格遵循前一步给出的国奖级建模方案，不得随意降级或更换模型\n\n• 本步完成后输出「赛题分析标准化交接包」，供下一步读取\n\n模式二：独立模式（单独使用本提示词时自动启用）\n\n• 未检测到前一步交接包 → 自动进入独立模式，无需依托任何前序提示词\n\n• 独立模式下自行完成前置工作：本步是全流程第一步，独立模式即为默认模式，直接基于题目和附件数据进行分析\n\n• 独立模式下输出质量与串联模式完全一致，同样达到国奖级标准\n\n• 本步完成后同样输出「赛题分析标准化交接包」，可与其他步骤衔接\n\n模式三：检测评估+自动整改模式（V6.0核心升级·学员上传成果时自动启用）\n\n【V6.0核心升级】当检测到学员上传的是已有论文/解题思路/代码/图表等成果（而非原始题目+数据）时，自动进入检测评估+自动整改模式！不仅检测问题，还基于提示词要求自动修改优化，消除检测出的问题！\n\n• 功能1【检测】：将学员上传的成果与国奖级标准进行多维度对比检测，评估是否达到国赛国奖级要求\n\n• 功能2【自动整改】：基于检测出的问题，按照本提示词的国奖级要求自动修改和优化学员上传的成果，消除问题\n\n• 评估维度：题型判断准确性/隐含条件挖掘深度/模型推荐合理性/创新点质量/评分点覆盖度/题意理解准确性\n\n• 整改流程：①多维度检测→②生成HTML检测报告→③按优先级(P0→P1→P2)自动整改→④整改后复检→⑤输出整改后成果+HTML整改报告(含整改前后对比)\n\n• 整改原则：能自动修改的自动修改（如格式/排版/公式/图表/代码），不能自动修改的给出详细修改方案（如模型重构/创新点设计），不得只检测不整改！\n\n• 输出：强制输出①整改后的成果文件（修改后的论文/代码/图表）②HTML格式的整改报告（文件名：整改报告_学员成果名称.html），报告最开始给出检测结果总览，然后列出整改清单+整改前后对比+复检结果\n\n• HTML整改报告必须包含8个部分：①检测结果总览(等级+总分+核心问题) ②多维度评分可视化 ③分维度详细分析 ④国奖级标准对照表 ⑤优先级整改清单(P0/P1/P2) ⑥整改前后对比(逐项展示修改内容) ⑦复检结果(整改后重新检测得分) ⑧底部信息栏\n\n• 评估等级：国奖级(≥90分) / 国一(80-89) / 国二(70-79) / 省一(60-69) / 省二(50-59) / 需大幅改进(<50)\n\n• 如学员明确只需要检测不需要整改，则只输出HTML检测报告；默认执行检测+自动整改一体化\n\n「赛题分析标准化交接包」输出格式（强制）\n\n本步完成后必须输出以下结构化交接包（JSON格式），供下一步自动读取：\n\n{ "题型": "A/B/C/D/E/混合" "各小问国奖版推荐模型": "问题一:XXX模型; 问题二:XXX模型..." "核心创新点清单": "创新点1:XXX(怎么做+效果+验证); 创新点2:XXX..." "关键隐含条件清单": "隐含条件1:XXX(数学表达); 隐含条件2:XXX..." "数据预处理重点": "缺失值处理/异常值处理/特征工程/防泄露要点" "检验方向建议": "问题一:灵敏度分析; 问题二:误差分析..." "评分点与易错点": "评分点:XXX; 易错点:XXX..."}\n\n【三模式铁律】无论哪种模式，输出质量标准完全一致！串联模式必须严格遵循前一步方案，独立模式必须自行完成前置工作，检测评估+自动整改模式必须既检测又整改，不得只检测不整改！不得因模式不同而降低质量！\n\n──────────────────────────────────────────────────\n\n一、输入（三模式）\n\n• 串联模式：无（本步是第一步）\n\n• 独立模式：赛题题目+附件数据（默认模式）\n\n• 检测评估模式：学员上传的赛题分析报告/解题思路文档\n\n二、输出\n\n• 解题模式：①赛题分析报告 ②8列速查表 ③国奖版推荐模型 ④核心创新点清单 ⑤隐含条件清单 ⑥数据预处理重点 ⑦标准化交接包\n\n• 检测评估模式：HTML评估报告（强制）\n\n三、国奖优秀论文赛题分析共性特点（补充原始细节）\n\n• 隐含条件挖掘深度：国奖论文隐含条件数量≥显性条件50%，每条有数学表达和建模影响\n\n• 模型推荐精准：直接给出国奖级创新模型，而非泛泛的「可以用优化模型」\n\n• 创新点具体：每个创新点说明「创新什么+为什么+怎么做+预期效果+如何验证」五要素\n\n• 评分导向：明确指出每个小问的评分点(3-5个)和易错点(2-3个)\n\n• 题型判断准确：A题机理优化/B题机理优化/C题数据分析/D题运筹优化/E题机理预测\n\n四、题意理解的常见误区（必须避免·补充原始细节）\n\n• 误区1：只看显性条件，忽略隐含条件（最致命）\n\n• 误区2：把问题想简单，用过于基础的模型（如只用线性规划解决复杂优化）\n\n• 误区3：模型推荐泛泛而谈，不具体到算法和创新点\n\n• 误区4：忽略题目中的约束条件（如额定功率、时间限制、资源约束）\n\n• 误区5：不区分省奖版和国奖版，直接给最简单的模型\n\n五、8大分析维度\n\n维度\n\n核心内容\n\n1 题目背景\n\n领域+核心问题+现实价值+评委考察意图\n\n2 已知条件\n\n逐句列出显性条件+数据+参数+约束+附件信息\n\n3 隐含条件(最高优先级)\n\n6维度挖掘：物理定律/数学约束/数据特征/边界条件/常识假设/评分导向\n\n4 核心要求\n\n每小问核心目标+评分点(3-5个)+易错点(2-3个)\n\n5 数学本质\n\n问题类型(优化/预测/分类/评价/机理)+数学工具+变量目标约束\n\n6 数据特征\n\n数据质量+分布+相关性+时空特征(C题重点)\n\n7 难点挑战\n\n建模/求解/数据/创新难点+解决策略\n\n8 创新空间\n\n算法改进/跨领域迁移/多模型融合+省奖国奖策略\n\n六、隐含条件挖掘（获奖关键）\n\n隐含条件数量必须≥显性条件的50%！每条按五要素：描述+来源+数学表达+建模影响+遗漏后果\n\n• 6维度：①物理/实际定律 ②数学约束 ③数据特征 ④边界条件 ⑤常识假设 ⑥评分导向\n\n七、省奖/国奖双轨思路\n\n版本\n\n要求\n\n省奖版\n\n经典成熟模型，实现简单稳妥，有基本问题特化处理\n\n国奖版(最终建模以此为准)\n\n经典模型基础上有针对性改进，至少1个真创新点(五要素：什么+为什么+怎么做+效果+验证)\n\n八、8列速查表（强制输出）\n\n列\n\n内容\n\n1\n\n小问编号\n\n2\n\n核心要求\n\n3\n\n数学本质\n\n4\n\n省奖版模型\n\n5\n\n国奖版模型\n\n6\n\n核心创新点\n\n7\n\n关键评分点\n\n8\n\n高频易错点\n\n九、检测评估模式评估维度\n\n维度\n\n国奖级标准\n\n评估要点\n\n题型判断\n\n准确判断题型(A/B/C/D/E)\n\n是否正确判断题型，是否说明判断依据\n\n隐含条件挖掘\n\n≥显性条件50%，每条有数学表达\n\n隐含条件数量、深度、数学表达、建模影响\n\n模型推荐\n\n直接给出国奖级创新模型\n\n模型是否具体到算法，是否有创新点，是否适配题目\n\n创新点质量\n\n每个创新点五要素完整\n\n创新点是否真创新(非简单应用)，五要素是否完整\n\n评分点覆盖\n\n每问3-5个评分点\n\n是否覆盖主要评分点，是否指出易错点\n\n题意理解\n\n无明显误解\n\n是否误解题目要求，是否忽略约束条件\n\n十、本提示词整改能力（检测+自动整改）\n\n整改类型\n\n可自动整改的内容\n\n整改方式\n\nP0致命\n\n题型判断错误、隐含条件严重不足、模型推荐过于简单\n\n重新判断题型+补充隐含条件+升级为国奖级创新模型\n\nP1重要\n\n创新点不具体、评分点覆盖不全、题意理解有偏差\n\n补充创新点五要素+补充评分点+修正题意理解\n\nP2优化\n\n格式排版、表述不够学术、结构不够清晰\n\n优化格式+学术化表述+调整结构\n\n需手动\n\n模型完全错误需要重构、核心思路完全偏离\n\n给出详细的重构方案和建议，需学员确认后执行\n\n整改后输出：修改后的赛题分析报告_已整改.docx + HTML整改报告（含整改前后对比+复检结果）\n\n──────────────────────────────────────────────────\n\n【赛题分析V6.0结束】解题模式输出标准化交接包，检测评估模式输出HTML报告。', '低', 0, 1, '2026-09-16 08:33:30', '2026-09-16 08:33:30');
INSERT IGNORE INTO `contract` VALUES (16, 2, '01_数学建模国赛【赛题分析】万能提示词', '劳动合同', '', '', NULL, '数学建模国赛{赛题分析}万能提示词\n\n（检测/修改/撰写三模式完整版）\n\n第1步：对赛题进行深度分析，输出分析报告+8列速查表+国奖级模型推荐+标准化交接包。支持检测评估模式。\n\n【通用规范引用·V6.0】排版格式、公式零乱码、流程图与示意图、HTML要点解析、三模式运行机制、检测评估+自动整改、HTML整改报告格式等通用规范，详见《超级提示词V6.0》。V6.0核心：①三模式运行(串联+独立+检测整改) ②检测+自动整改一体化 ③标准化交接包 ④自动检测适配 ⑤章节对标优秀论文 ⑥C题数据侧写 ⑦示意图+算法步骤表+完整模型给出 ⑧检测整改强制输出HTML报告+整改后成果。\n\n────────────────────────────────────────────────\n\n【三模式运行机制】V6.0核心\n\n本提示词支持三种运行模式，自动检测适配，确保串联性、独立性、检测评估能力三保障：\n\n模式一：串联模式（按顺序运行时自动启用）\n\n• 运行开始时自动检测是否存在「无（全流程第一步）标准化交接包」\n\n• 检测到交接包 → 自动读取其中的国奖级推荐模型、创新点、预处理方案等核心数据，基于其继续执行\n\n• 严格遵循前一步给出的国奖级建模方案，不得随意降级或更换模型\n\n• 本步完成后输出「赛题分析标准化交接包」，供下一步读取\n\n模式二：独立模式（单独使用本提示词时自动启用）\n\n• 未检测到前一步交接包 → 自动进入独立模式，无需依托任何前序提示词\n\n• 独立模式下自行完成前置工作：本步是全流程第一步，独立模式即为默认模式，直接基于题目和附件数据进行分析\n\n• 独立模式下输出质量与串联模式完全一致，同样达到国奖级标准\n\n• 本步完成后同样输出「赛题分析标准化交接包」，可与其他步骤衔接\n\n模式三：检测评估+自动整改模式（V6.0核心升级·学员上传成果时自动启用）\n\n【V6.0核心升级】当检测到学员上传的是已有论文/解题思路/代码/图表等成果（而非原始题目+数据）时，自动进入检测评估+自动整改模式！不仅检测问题，还基于提示词要求自动修改优化，消除检测出的问题！\n\n• 功能1【检测】：将学员上传的成果与国奖级标准进行多维度对比检测，评估是否达到国赛国奖级要求\n\n• 功能2【自动整改】：基于检测出的问题，按照本提示词的国奖级要求自动修改和优化学员上传的成果，消除问题\n\n• 评估维度：题型判断准确性/隐含条件挖掘深度/模型推荐合理性/创新点质量/评分点覆盖度/题意理解准确性\n\n• 整改流程：①多维度检测→②生成HTML检测报告→③按优先级(P0→P1→P2)自动整改→④整改后复检→⑤输出整改后成果+HTML整改报告(含整改前后对比)\n\n• 整改原则：能自动修改的自动修改（如格式/排版/公式/图表/代码），不能自动修改的给出详细修改方案（如模型重构/创新点设计），不得只检测不整改！\n\n• 输出：强制输出①整改后的成果文件（修改后的论文/代码/图表）②HTML格式的整改报告（文件名：整改报告_学员成果名称.html），报告最开始给出检测结果总览，然后列出整改清单+整改前后对比+复检结果\n\n• HTML整改报告必须包含8个部分：①检测结果总览(等级+总分+核心问题) ②多维度评分可视化 ③分维度详细分析 ④国奖级标准对照表 ⑤优先级整改清单(P0/P1/P2) ⑥整改前后对比(逐项展示修改内容) ⑦复检结果(整改后重新检测得分) ⑧底部信息栏\n\n• 评估等级：国奖级(≥90分) / 国一(80-89) / 国二(70-79) / 省一(60-69) / 省二(50-59) / 需大幅改进(<50)\n\n• 如学员明确只需要检测不需要整改，则只输出HTML检测报告；默认执行检测+自动整改一体化\n\n「赛题分析标准化交接包」输出格式（强制）\n\n本步完成后必须输出以下结构化交接包（JSON格式），供下一步自动读取：\n\n{ "题型": "A/B/C/D/E/混合" "各小问国奖版推荐模型": "问题一:XXX模型; 问题二:XXX模型..." "核心创新点清单": "创新点1:XXX(怎么做+效果+验证); 创新点2:XXX..." "关键隐含条件清单": "隐含条件1:XXX(数学表达); 隐含条件2:XXX..." "数据预处理重点": "缺失值处理/异常值处理/特征工程/防泄露要点" "检验方向建议": "问题一:灵敏度分析; 问题二:误差分析..." "评分点与易错点": "评分点:XXX; 易错点:XXX..."}\n\n【三模式铁律】无论哪种模式，输出质量标准完全一致！串联模式必须严格遵循前一步方案，独立模式必须自行完成前置工作，检测评估+自动整改模式必须既检测又整改，不得只检测不整改！不得因模式不同而降低质量！\n\n──────────────────────────────────────────────────\n\n一、输入（三模式）\n\n• 串联模式：无（本步是第一步）\n\n• 独立模式：赛题题目+附件数据（默认模式）\n\n• 检测评估模式：学员上传的赛题分析报告/解题思路文档\n\n二、输出\n\n• 解题模式：①赛题分析报告 ②8列速查表 ③国奖版推荐模型 ④核心创新点清单 ⑤隐含条件清单 ⑥数据预处理重点 ⑦标准化交接包\n\n• 检测评估模式：HTML评估报告（强制）\n\n三、国奖优秀论文赛题分析共性特点（补充原始细节）\n\n• 隐含条件挖掘深度：国奖论文隐含条件数量≥显性条件50%，每条有数学表达和建模影响\n\n• 模型推荐精准：直接给出国奖级创新模型，而非泛泛的「可以用优化模型」\n\n• 创新点具体：每个创新点说明「创新什么+为什么+怎么做+预期效果+如何验证」五要素\n\n• 评分导向：明确指出每个小问的评分点(3-5个)和易错点(2-3个)\n\n• 题型判断准确：A题机理优化/B题机理优化/C题数据分析/D题运筹优化/E题机理预测\n\n四、题意理解的常见误区（必须避免·补充原始细节）\n\n• 误区1：只看显性条件，忽略隐含条件（最致命）\n\n• 误区2：把问题想简单，用过于基础的模型（如只用线性规划解决复杂优化）\n\n• 误区3：模型推荐泛泛而谈，不具体到算法和创新点\n\n• 误区4：忽略题目中的约束条件（如额定功率、时间限制、资源约束）\n\n• 误区5：不区分省奖版和国奖版，直接给最简单的模型\n\n五、8大分析维度\n\n维度\n\n核心内容\n\n1 题目背景\n\n领域+核心问题+现实价值+评委考察意图\n\n2 已知条件\n\n逐句列出显性条件+数据+参数+约束+附件信息\n\n3 隐含条件(最高优先级)\n\n6维度挖掘：物理定律/数学约束/数据特征/边界条件/常识假设/评分导向\n\n4 核心要求\n\n每小问核心目标+评分点(3-5个)+易错点(2-3个)\n\n5 数学本质\n\n问题类型(优化/预测/分类/评价/机理)+数学工具+变量目标约束\n\n6 数据特征\n\n数据质量+分布+相关性+时空特征(C题重点)\n\n7 难点挑战\n\n建模/求解/数据/创新难点+解决策略\n\n8 创新空间\n\n算法改进/跨领域迁移/多模型融合+省奖国奖策略\n\n六、隐含条件挖掘（获奖关键）\n\n隐含条件数量必须≥显性条件的50%！每条按五要素：描述+来源+数学表达+建模影响+遗漏后果\n\n• 6维度：①物理/实际定律 ②数学约束 ③数据特征 ④边界条件 ⑤常识假设 ⑥评分导向\n\n七、省奖/国奖双轨思路\n\n版本\n\n要求\n\n省奖版\n\n经典成熟模型，实现简单稳妥，有基本问题特化处理\n\n国奖版(最终建模以此为准)\n\n经典模型基础上有针对性改进，至少1个真创新点(五要素：什么+为什么+怎么做+效果+验证)\n\n八、8列速查表（强制输出）\n\n列\n\n内容\n\n1\n\n小问编号\n\n2\n\n核心要求\n\n3\n\n数学本质\n\n4\n\n省奖版模型\n\n5\n\n国奖版模型\n\n6\n\n核心创新点\n\n7\n\n关键评分点\n\n8\n\n高频易错点\n\n九、检测评估模式评估维度\n\n维度\n\n国奖级标准\n\n评估要点\n\n题型判断\n\n准确判断题型(A/B/C/D/E)\n\n是否正确判断题型，是否说明判断依据\n\n隐含条件挖掘\n\n≥显性条件50%，每条有数学表达\n\n隐含条件数量、深度、数学表达、建模影响\n\n模型推荐\n\n直接给出国奖级创新模型\n\n模型是否具体到算法，是否有创新点，是否适配题目\n\n创新点质量\n\n每个创新点五要素完整\n\n创新点是否真创新(非简单应用)，五要素是否完整\n\n评分点覆盖\n\n每问3-5个评分点\n\n是否覆盖主要评分点，是否指出易错点\n\n题意理解\n\n无明显误解\n\n是否误解题目要求，是否忽略约束条件\n\n十、本提示词整改能力（检测+自动整改）\n\n整改类型\n\n可自动整改的内容\n\n整改方式\n\nP0致命\n\n题型判断错误、隐含条件严重不足、模型推荐过于简单\n\n重新判断题型+补充隐含条件+升级为国奖级创新模型\n\nP1重要\n\n创新点不具体、评分点覆盖不全、题意理解有偏差\n\n补充创新点五要素+补充评分点+修正题意理解\n\nP2优化\n\n格式排版、表述不够学术、结构不够清晰\n\n优化格式+学术化表述+调整结构\n\n需手动\n\n模型完全错误需要重构、核心思路完全偏离\n\n给出详细的重构方案和建议，需学员确认后执行\n\n整改后输出：修改后的赛题分析报告_已整改.docx + HTML整改报告（含整改前后对比+复检结果）\n\n──────────────────────────────────────────────────\n\n【赛题分析V6.0结束】解题模式输出标准化交接包，检测评估模式输出HTML报告。', '低', 0, 1, '2026-09-16 08:45:18', '2026-09-16 08:45:18');
INSERT IGNORE INTO `contract` VALUES (17, 2, '示例劳动合同', '劳动合同', 'XX科技有限公司', '张三', NULL, '劳动合同\n甲方：XX科技有限公司  乙方：张三\n一、合同期限：自2024年7月1日起至2025年6月30日止，其中试用期为6个月。\n二、工资：月薪6000元，每月15日发放；试用期工资按80%发放。\n三、社保：甲方自乙方转正后为其缴纳社会保险。\n四、加班：因工作需要加班的，公司安排调休，不另行支付加班费。\n五、竞业限制：乙方离职后两年内不得从事同类业务，公司不支付经济补偿。\n六、解除：乙方提前离职需向甲方支付违约金20000元。', '高', 2, 1, '2026-09-16 09:11:12', '2026-09-16 09:11:12');
