INSERT IGNORE INTO `knowledge_article` VALUES (1, '试用期到底能约定多久？一张表看懂', '试用期不是公司想定多久就定多久，法律有明确的期限上限。', '试用期不是公司想定多久就定多久，法律有明确的期限上限。\n\n本文围绕“试用期到底能约定多久？一张表看懂”这一职场高频问题展开，结合《劳动合同法》《劳动法》《社会保险法》等法律法规，逐条梳理适用情形、举证要点与维权路径。建议读者在遇到具体问题时，先固定证据，再按“协商 → 投诉 → 仲裁 → 诉讼”的顺序推进，避免因超期或证据缺失而丧失权利。', '劳动合同', '职小法编辑部', 1284, 96, 1, '2026-06-19 09:00:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `knowledge_article` VALUES (2, '被拖欠工资，正确的维权顺序是什么？', '先协商、再投诉、后仲裁，每一步都要留证据。', '先协商、再投诉、后仲裁，每一步都要留证据。\n\n本文围绕“被拖欠工资，正确的维权顺序是什么？”这一职场高频问题展开，结合《劳动合同法》《劳动法》《社会保险法》等法律法规，逐条梳理适用情形、举证要点与维权路径。建议读者在遇到具体问题时，先固定证据，再按“协商 → 投诉 → 仲裁 → 诉讼”的顺序推进，避免因超期或证据缺失而丧失权利。', '工资报酬', '职小法编辑部', 2156, 173, 1, '2026-05-13 09:00:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `knowledge_article` VALUES (3, '没签劳动合同，你能拿多少二倍工资？', '从用工满一个月的次日起算，最长可主张11个月。', '从用工满一个月的次日起算，最长可主张11个月。\n\n本文围绕“没签劳动合同，你能拿多少二倍工资？”这一职场高频问题展开，结合《劳动合同法》《劳动法》《社会保险法》等法律法规，逐条梳理适用情形、举证要点与维权路径。建议读者在遇到具体问题时，先固定证据，再按“协商 → 投诉 → 仲裁 → 诉讼”的顺序推进，避免因超期或证据缺失而丧失权利。', '劳动合同', '职小法编辑部', 1893, 141, 1, '2026-07-27 09:00:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `knowledge_article` VALUES (4, '加班费怎么算？1.5倍、2倍、3倍分别对应什么情况', '法定节假日加班必须给3倍，且不能用调休替代。', '法定节假日加班必须给3倍，且不能用调休替代。\n\n本文围绕“加班费怎么算？1.5倍、2倍、3倍分别对应什么情况”这一职场高频问题展开，结合《劳动合同法》《劳动法》《社会保险法》等法律法规，逐条梳理适用情形、举证要点与维权路径。建议读者在遇到具体问题时，先固定证据，再按“协商 → 投诉 → 仲裁 → 诉讼”的顺序推进，避免因超期或证据缺失而丧失权利。', '工资报酬', '职小法编辑部', 3042, 268, 1, '2026-07-16 09:00:00', '2026-09-15 20:48:27');
