INSERT IGNORE INTO `law_article` VALUES (1, '中华人民共和国劳动合同法', '第十条', 10, '劳动合同', '订立书面劳动合同', '建立劳动关系，应当订立书面劳动合同。已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。', '书面劳动合同 一个月 用工', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:06');
INSERT IGNORE INTO `law_article` VALUES (2, '中华人民共和国劳动合同法', '第十九条', 19, '劳动合同', '试用期期限', '劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。同一用人单位与同一劳动者只能约定一次试用期。', '试用期 期限 六个月 一个月', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:06');
INSERT IGNORE INTO `law_article` VALUES (3, '中华人民共和国劳动合同法', '第二十条', 20, '工资报酬', '试用期工资', '劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。', '试用期工资 百分之八十 最低工资', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (4, '中华人民共和国劳动合同法', '第三十七条', 37, '解除终止', '劳动者预告解除', '劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。', '辞职 提前三十日 试用期 三日', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (5, '中华人民共和国劳动合同法', '第三十八条', 38, '解除终止', '劳动者即时解除', '用人单位有下列情形之一的，劳动者可以解除劳动合同：（一）未按照劳动合同约定提供劳动保护或者劳动条件的；（二）未及时足额支付劳动报酬的；（三）未依法为劳动者缴纳社会保险费的；（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的。', '拖欠工资 未缴社保 被迫离职 即时解除', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (6, '中华人民共和国劳动合同法', '第三十九条', 39, '解除终止', '用人单位过失性辞退', '劳动者有下列情形之一的，用人单位可以解除劳动合同：（一）在试用期间被证明不符合录用条件的；（二）严重违反用人单位的规章制度的；（三）严重失职，营私舞弊，给用人单位造成重大损害的；（四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的。', '辞退 不符合录用条件 严重违纪', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (7, '中华人民共和国劳动合同法', '第四十七条', 47, '解除终止', '经济补偿标准', '经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。', '经济补偿 一年一个月 平均工资', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (8, '中华人民共和国劳动合同法', '第八十二条', 82, '劳动合同', '未签合同的二倍工资', '用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。', '二倍工资 未签合同', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:06');
INSERT IGNORE INTO `law_article` VALUES (9, '中华人民共和国劳动合同法', '第八十七条', 87, '解除终止', '违法解除的赔偿金', '用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。', '违法解除 二倍赔偿金 2N', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (10, '中华人民共和国劳动合同法', '第二十三条', 23, '竞业限制', '竞业限制与补偿', '用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。', '竞业限制 保密 补偿', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (11, '中华人民共和国劳动合同法', '第九条', 9, '其他', '禁止收取财物', '用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。', '扣押证件 押金 担保', '2013:07:01', 'manual', '2c909fdd678bf17901678bf74d7106b3', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (12, '中华人民共和国劳动法', '第四十四条', 44, '工资报酬', '加班工资标准', '有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。', '加班费 1.5倍 2倍 3倍', '2018:12:29', 'manual', 'ff8080816f135f46016f20f16ee11737', '2026-09-15 20:48:27', '2026-09-21 20:50:44');
INSERT IGNORE INTO `law_article` VALUES (13, '中华人民共和国社会保险法', '第五十八条', 58, '社会保险', '社保登记义务', '用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。', '社保 五险 三十日 登记', '2018:12:29', 'manual', 'ff8080816f135f46016f210989b9179a', '2026-09-15 20:48:27', '2026-09-21 20:50:06');
INSERT IGNORE INTO `law_article` VALUES (14, '中华人民共和国劳动争议调解仲裁法', '第二十七条', 27, '其他', '仲裁时效', '劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。', '仲裁时效 一年 拖欠工资', '2008:05:01', 'manual', '2c909fdd678bf17901678bf64f28039d', '2026-09-15 20:48:27', '2026-09-21 20:50:06');
