INSERT IGNORE INTO `qa_record` VALUES (1, 1, '老板拖欠我3万工资2个月了怎么办？', '拖欠用人单位拖欠工资属于违法行为。您可以：1) 与公司协商并保留书面催告记录；2) 向当地劳动保障监察大队投诉；3) 直接申请劳动仲裁，无需先投诉。依据《劳动合同法》第三十八条，用人单位未及时足额支付劳动报酬的，劳动者可以解除劳动合同并要求经济补偿。', '工资报酬', 1, 42, '2026-08-01 14:04:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (2, 2, '试用期被辞退有补偿吗？', '要看辞退理由。若公司不能证明您“不符合录用条件”，属于违法解除，应支付 2N 赔偿金；若确实不符合录用条件且有证据，则无补偿。试用期不是“随意期”，用人单位仍需举证。', '解除终止', 1, 38, '2026-08-22 17:49:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (3, 3, '没签劳动合同怎么证明劳动关系？', '可凭以下证据形成证据链：工资银行流水、工牌工服照片、考勤打卡截图、工作群聊天记录、同事证言、社保缴纳记录、盖有公章的文件。依据《劳动合同法》第八十二条，超过一个月未签合同的，可主张二倍工资。', '劳动合同', 1, 51, '2026-08-18 08:44:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (4, 4, '公司要求加班但不给加班费合法吗？', '不合法。《劳动法》第四十四条规定，延长工作时间应支付不低于 150% 的工资，休息日不能补休的支付 200%，法定节假日支付 300%。若公司长期不支付，可申请仲裁并主张解除劳动合同的经济补偿。', '工资报酬', 1, 33, '2026-08-30 12:50:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (5, 5, '试用期最长能约定多久？', '按《劳动合同法》第十九条：合同期3个月以上不满1年的，试用期不超过1个月；1年以上不满3年的，不超过2个月；3年以上及无固定期限的，不超过6个月。同一单位与同一劳动者只能约定一次试用期。', '劳动合同', 1, 47, '2026-08-16 12:23:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (6, 6, '被口头辞退怎么办？', '口头辞退风险较大，公司常事后否认。建议：1) 立即通过微信/邮件要求公司出具书面解除通知；2) 保留被要求离职的录音；3) 正常出勤打卡，避免被认定旷工。若公司违法解除，可主张 2N 赔偿金。', '解除终止', 1, 29, '2026-08-31 17:40:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (7, 7, '竞业限制有补偿吗？', '有。依据《劳动合同法》第二十三条，约定竞业限制的，须在竞业限制期限内按月给予经济补偿。用人单位三个月未支付补偿的，劳动者可请求解除竞业限制约定。补偿标准一般不低于离职前十二个月平均工资的30%。', '竞业限制', 1, 26, '2026-08-18 20:49:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (8, 8, '公司不缴社保怎么维权？', '《社会保险法》第五十八条要求用人单位自用工之日起30日内办理社保登记。公司不缴的，可向社保征收机构投诉要求补缴，也可依据《劳动合同法》第三十八条以此为由解除劳动合同并主张经济补偿。', '社会保险', 1, 35, '2026-08-09 19:09:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (9, 9, '入职公司收了我500元押金合法吗？', '不合法。《劳动合同法》第九条明确规定，用人单位招用劳动者不得收取财物。您有权要求返还，并可向劳动行政部门举报，由行政部门责令限期退还并按每人500元以上2000元以下标准处以罚款。', '其他', 1, 22, '2026-08-18 13:09:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (10, 10, '申请劳动仲裁的时效是多久？', '一般为一年，从知道或应当知道权利被侵害之日起算。但拖欠劳动报酬的争议，在劳动关系存续期间不受一年限制；劳动关系终止的，应自终止之日起一年内提出。', '其他', 1, 18, '2026-08-21 08:23:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (11, 11, '公司单方面调岗降薪我能拒绝吗？', '劳动合同的变更需双方协商一致并采用书面形式。公司未经协商单方调岗降薪，属于违约。您可以书面拒绝，若公司据此解除合同，属于违法解除，可主张 2N 赔偿金。', '劳动合同', 1, 31, '2026-08-28 11:16:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (12, 12, '经济补偿N、N+1、2N分别是什么？', 'N 是法定经济补偿，按工作年限每满一年一个月工资（《劳动合同法》第四十七条）；N+1 是未提前30日书面通知时额外支付一个月工资的代通知金；2N 是用人单位违法解除时的赔偿金（第八十七条）。', '解除终止', 1, 56, '2026-08-14 14:47:00', '2026-09-15 20:48:27');
INSERT IGNORE INTO `qa_record` VALUES (13, 2, '昨天正常上班 今天就让我滚蛋', '根据您描述的情况，初步分析如下：\n\n【初步结论】您的情况在现行劳动法律法规中有明确依据，建议优先通过书面方式主张权利，并注意保存证据。\n\n【法律依据】\n1. 《中华人民共和国劳动法》第四十四条（加班工资标准）：有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。\n2. 《中华人民共和国劳动法》第四十四条（加班工资标准）：有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。\n\n【建议步骤】\n1. 固定证据：保留劳动合同、工资流水、考勤记录、聊天记录等；\n2. 书面沟通：以邮件或微信向用人单位提出明确诉求，留痕；\n3. 行政投诉：向用工所在地劳动保障监察大队投诉；\n4. 申请仲裁：向劳动合同履行地或用人单位所在地的劳动人事争议仲裁委员会申请仲裁，一般时效为一年。\n\n提示：以上内容由系统依据法规库自动生成，仅供参考，具体案件建议咨询专业律师。', '劳动合同', 1, 0, '2026-09-15 21:06:59', '2026-09-15 21:06:59');
